"""Generates go/internal/smbios/devices_gen.go from the ORIGINAL
Scripts/datasets/mac_model_data.py, so the Go table cannot drift by hand.

Usage: python3 -I go/tools/gen_mac_devices.py <repo_root> > go/internal/smbios/devices_gen.go
"""

import sys

sys.path.insert(0, sys.argv[1])

from Scripts.datasets.mac_model_data import mac_devices  # noqa: E402

HEADER = """// Code generated by go/tools/gen_mac_devices.py from
// Scripts/datasets/mac_model_data.py. DO NOT EDIT.

package smbios

// devices is the mac_devices table of the original project, in the same order.
var devices = []Device{
"""


def go_str(value):
    if value is None:
        return '""'
    return '"' + value.replace("\\", "\\\\").replace('"', '\\"') + '"'


sys.stdout.write(HEADER)
for d in mac_devices:
    sys.stdout.write(
        "\t{Name: %s, CPU: %s, CPUGeneration: %s, DiscreteGPU: %s, InitialSupport: %s, LastSupportedVersion: %s},\n"
        % (go_str(d.name), go_str(d.cpu), go_str(d.cpu_generation), go_str(d.discrete_gpu),
           go_str(d.initial_support), go_str(d.last_supported_version))
    )
sys.stdout.write("}\n")
